function result=shrinkage_covariance(y,o)
%SHRINKAGE_COVARIANCE 与sklearn OAS约定一致的收缩公式，保留MLE样本分母n。
[n,p]=size(y);if ~isnumeric(y)||~ismatrix(y)||~isreal(y)||n<3||p<2||any(~isfinite(y),'all')||~isscalar(o.maxFeatures)||~isfinite(o.maxFeatures)||o.maxFeatures<2||o.maxFeatures~=fix(o.maxFeatures)||p>o.maxFeatures||~isscalar(o.standardize)||~ismember(o.standardize,[false true]),error('cog:ShrinkageInput','Finite n>=3/p>=2 matrix and valid feature budget/standardization required');end
mu=mean(double(y),1);x=double(y)-mu;scale=ones(1,p);if o.standardize,scale=std(x,0,1);if any(scale==0),error('cog:ShrinkageConstant','Standardization requested with constant feature');end;x=x./scale;end
s=(x'*x)/n;target=trace(s)/p;if target<=0,error('cog:ShrinkageConstant','No positive total feature variance');end;alpha=mean(s.^2,'all');den=(n+1)*(alpha-target^2/p);if den<=0,rho=1;else,rho=max(0,min(1,(alpha+target^2)/den));end
covariance=(1-rho)*s+rho*target*eye(p);[l,flag]=chol(covariance,'lower');if flag~=0,error('cog:ShrinkageNumerics','Shrunk covariance not positive definite; check numerical scale');end;precision=l'\(l\eye(p));sd=sqrt(diag(covariance));correlation=covariance./(sd*sd');pd=sqrt(diag(precision));partial=-precision./(pd*pd');partial(1:p+1:end)=1;
result=struct('covariance',covariance,'precision',precision,'correlation',correlation,'partialCorrelation',partial,'empiricalCovarianceMle',s,'shrinkage',rho,'targetMeanVariance',target,'dataMean',mu,'dataScale',scale,'nRows',n,'nFeatures',p,'options',o,'note','OAS formula matches sklearn convention omitting 2/p terms of original Chen equation23; MLE covariance denominator n. Positive identity shrinkage handles p>n but is not sparse graphical lasso. Autocorrelated BOLD rows are not proven iid; no unbiased effective-sample or inferential interpretation. Optional feature standardization changes shrinkage target.');
end
